code_sketch:
sealed interface Shape
data class Circle(val radius: Double) : Shape
data class Square(val side: Double) : Shape

fun collide(a: Shape, b: Shape): String = when (a) {
    is Circle -> when (b) { is Square -> "circle vs square"; is Circle -> "two circles" }
    is Square -> when (b) { is Circle -> collide(b, a); is Square -> "two squares" }   // canonicalise
}

