    is Circle -> when (b) { is Square -> "circle vs square"; is Circle -> "two circles" }
    is Square -> when (b) { is Circle -> collide(b, a); is Square -> "two squares" }   // canonicalise
}

interface ShapeVisitor {
    fun visit(circle: Circle)
    fun visit(square: Square)
}
sealed interface Shape { fun accept(v: ShapeVisitor) }
class Circle(val radius: Double) : Shape {
    override fun accept(v: ShapeVisitor) = v.visit(this)   // dispatch #2 target
}
